$p="$env:APPDATA\AnyDesk"; if(!(Test-Path $p)){Write-Host "La carpeta no existe." -ForegroundColor Yellow;return}; $a=@(Get-ChildItem $p -Force -Recurse -ErrorAction SilentlyContinue); $t=$a.Count; if($t -eq 0){Write-Host "No hay nada que eliminar." -ForegroundColor Cyan;return}; $i=0; foreach($x in $a){try{if(Test-Path -LiteralPath $x.FullName){Remove-Item -LiteralPath $x.FullName -Force -Recurse -ErrorAction Stop}}catch{};$i++;Write-Progress -Activity "Eliminando contenido de AnyDesk" -Status "$i de $t elementos" -PercentComplete ([int](100*$i/$t))}; Get-ChildItem $p -Force -ErrorAction SilentlyContinue | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue; Write-Progress -Activity "Eliminando contenido de AnyDesk" -Completed; if((Get-ChildItem $p -Force -ErrorAction SilentlyContinue | Measure-Object).Count -eq 0){Write-Host "LISTO: carpeta AnyDesk vacía." -ForegroundColor Green}else{Write-Host "AVISO: algunos elementos no se pudieron eliminar." -ForegroundColor Yellow}
